function allMissions(){return allDates.flatMap(d=>rawMissionsFor(d))}
function renderFocusGoal(){const select=document.getElementById('focusGoalSelect'),display=document.getElementById('focusGoalDisplay'),clear=document.getElementById('focusGoalClear');if(!select)return;const dayMissions=missionsFor(selected),current=focusTimer.goal_task_key?allMissions().find(q=>q.id===focusTimer.goal_task_key):null,options=[...dayMissions];if(current&&!options.some(q=>q.id===current.id))options.unshift(current);select.innerHTML='<option value="">先選本輪唯一目標</option>'+options.map(q=>`<option value="${esc(q.id)}">${esc(q.subject)}・${esc(q.name)}${q.completed?' ✓':''}</option>`).join('');select.value=current?.id||'';display.textContent=rescueStep?`本輪小步驟｜${rescueStep}`:current?`本輪目標｜${current.subject}・${current.name}`:'尚未選擇本輪目標';clear.textContent=rescueStep?'先只完成這個小步驟，做完再決定下一步。':current?`通關條件：${current.clear}`:'選好目標後，通關條件會顯示在這裡。'}
async function changeFocusGoal(event){focusTimer.goal_task_key=event.target.value||null;rescueStep='';saveFocusRescueState();renderFocusGoal();setSyncing(true);await persistTimer();setSyncing(false);showToast(focusTimer.goal_task_key?'本輪目標已鎖定':'已清除本輪目標')}
function parseDistractionContent(raw){const text=String(raw||''),match=text.match(/^【([^】]+)】\s*/);if(!match)return{category:'thought',content:text};const category=Object.keys(DISTRACTION_CATEGORIES).find(key=>DISTRACTION_CATEGORIES[key]===match[1])||'thought';return{category,content:text.slice(match[0].length)}}
function renderDistractions(){const list=document.getElementById('distractionList');if(!list)return;list.innerHTML=distractions.length?distractions.slice(0,20).map(item=>{const parsed=parseDistractionContent(item.content);return`<div class="parking-item"><span><i class="parking-tag">${esc(DISTRACTION_CATEGORIES[parsed.category])}</i>${esc(parsed.content)}</span><button type="button" data-distraction-delete="${esc(item.id)}" aria-label="處理完成 ${esc(parsed.content)}" title="處理完畢">✓</button></div>`}).join(''):'<div class="parking-empty">目前沒有分心事項，專注力滿格 ✦</div>';list.querySelectorAll('[data-distraction-delete]').forEach(button=>button.onclick=()=>removeDistraction(button.dataset.distractionDelete));renderFocusReport()}
function combinedDistractionLog(){const map=new Map(distractionLog.map(item=>[String(item.id),item]));for(const item of distractions){const parsed=parseDistractionContent(item.content),id=String(item.id);if(!map.has(id))map.set(id,{id,category:parsed.category,content:parsed.content,created_at:item.created_at||new Date().toISOString(),resolved_at:null})}return[...map.values()]}
function renderFocusReport(){const grid=document.getElementById('focusReportGrid');if(!grid)return;const start=startOfWeek(new Date()),end=add(start,7),week=combinedDistractionLog().filter(item=>{const at=new Date(item.created_at);return at>=start&&at<end}),counts=Object.fromEntries(Object.keys(DISTRACTION_CATEGORIES).map(key=>[key,week.filter(item=>item.category===key).length])),max=Math.max(1,...Object.values(counts)),top=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0],resolved=week.filter(item=>item.resolved_at).length;document.getElementById('focusReportRange').textContent=`${start.getMonth()+1}/${start.getDate()}－${add(start,6).getMonth()+1}/${add(start,6).getDate()}`;grid.innerHTML=Object.entries(DISTRACTION_CATEGORIES).map(([key,label])=>`<article class="focus-cause"><span>${label}</span><b>${counts[key]}</b><div class="focus-cause-bar"><i style="width:${counts[key]/max*100}%"></i></div></article>`).join('');const advice={phone:'手機最容易拉走注意力；開始前把手機放到伸手碰不到的地方。',tired:'疲累是主要原因；今天優先選 15 分鐘模式，完成一輪就算贏。',stuck:'卡題是主要原因；先寫出已知條件，三分鐘沒進展就記下問題換下一題。',thought:'雜念最多；想到事情立刻停放，不必現在完成它。',environment:'環境干擾最多；開始前先準備水、耳機並清空桌面。'};document.getElementById('focusReportAdvice').textContent=week.length?`本週記錄 ${week.length} 次，已處理 ${resolved} 次。${advice[top]}`:'記錄第一次分心後，這裡會幫你找出最常見的原因。'}
async function createDistraction(content,category,input){content=String(content||'').trim().slice(0,120);category=DISTRACTION_CATEGORIES[category]?category:'thought';if(!content)return false;if(input)input.disabled=true;const stored=`【${DISTRACTION_CATEGORIES[category]}】 ${content}`,{data,error}=await db.from('distraction_items').insert({user_id:session.user.id,content:stored}).select().single();if(input)input.disabled=false;if(error){showToast('停放失敗，請再試一次',true);return false}distractions.push(data);distractionLog.push({id:String(data.id),category,content,created_at:data.created_at||new Date().toISOString(),resolved_at:null});saveFocusRescueState();if(input)input.value='';renderDistractions();showToast('已停好，現在回到本輪任務');return true}
