async function addQuickDistraction(event){event.preventDefault();await createDistraction(document.getElementById('focusQuickDistraction').value,document.getElementById('focusQuickCategory').value,document.getElementById('focusQuickDistraction'))}
async function removeDistraction(id){const previous=distractions,item=distractions.find(row=>String(row.id)===String(id));distractions=distractions.filter(row=>String(row.id)!==String(id));renderDistractions();const {error}=await db.from('distraction_items').delete().eq('id',id).eq('user_id',session.user.id);if(error){distractions=previous;renderDistractions();showToast('刪除失敗，請再試一次',true);return}const parsed=parseDistractionContent(item?.content),known=distractionLog.find(row=>String(row.id)===String(id));if(known)known.resolved_at=new Date().toISOString();else distractionLog.push({id:String(id),category:parsed.category,content:parsed.content,created_at:item?.created_at||new Date().toISOString(),resolved_at:new Date().toISOString()});saveFocusRescueState();renderDistractions();showToast('分心事項已處理')}
function totals(){const all=allMissions(),done=all.filter(q=>q.completed),xp=done.reduce((s,q)=>s+q.xp,0);return{all,done,xp,level:1+Math.floor(xp/500)}}
function streak(){const today=new Date();today.setHours(0,0,0,0);let s=0;for(let d=new Date(today>end?end:today);d>=start;d=add(d,-1)){const qs=missionsFor(d);if(qs.length&&qs.every(q=>q.completed))s++;else break}return s}
