function openScoreDialog(key){const exam=tests.find(t=>t.key===key);if(!exam)return;const result=examResults[key];document.getElementById('scoreExamKey').value=key;document.getElementById('scoreDialogTitle').textContent=result?'修改這場 Boss 成績':'輸入成績才能通關';document.getElementById('scoreExamMeta').textContent=`${exam.date.toLocaleDateString('zh-TW',{year:'numeric',month:'long',day:'numeric'})}・${exam.subject}・${exam.scope}`;document.getElementById('scoreInput').value=result?.score??'';document.getElementById('scoreNote').value=result?.note??'';document.getElementById('confirmExamClear').textContent=result?'✓ 更新戰績':'✓ 確認通關';document.getElementById('scoreDialog').showModal();setTimeout(()=>document.getElementById('scoreInput').focus(),80)}
