function render(){if(!session)return;const qs=missionsFor(selected),done=qs.filter(q=>q.completed).length,t=totals(),boss=nextBoss(),remain=diff(selected,boss.date),requiredToday=qs.filter(q=>q.required),requiredDone=requiredToday.filter(q=>q.completed).length,coverage=t.all.filter(q=>q.required&&q.date<='2026-10-04'),coverageDone=coverage.filter(q=>q.completed).length,coverageRate=coverage.length?Math.round(coverageDone/coverage.length*100):0;document.body.dataset.theme=profile.theme||'pink';document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.body).getPropertyValue('--pink').trim()||'#d91672';document.getElementById('heroHeadline').textContent=profile.headline;document.title=profile.headline;document.getElementById('dateLabel').textContent=selected.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'});document.getElementById('questTitle').textContent=`${selected.getMonth()+1}/${selected.getDate()} 今日關卡`;document.getElementById('xpValue').textContent=t.xp;document.getElementById('levelValue').textContent=t.level;document.getElementById('xpNeeded').textContent=500-(t.xp%500);document.getElementById('xpFill').style.width=`${(t.xp%500)/5}%`;document.getElementById('streakValue').textContent=streak();document.getElementById('completionValue').textContent=`${done}/${qs.length}`;document.getElementById('todayXp').textContent=`今日 ${qs.filter(q=>q.completed).reduce((s,q)=>s+q.xp,0)} XP`;document.getElementById('dailyProgress').textContent=requiredToday.length?`必讀 ${requiredDone}/${requiredToday.length}`:`${qs.length?Math.round(done/qs.length*100):0}%`;document.getElementById('coverageText').textContent=`必讀覆蓋 ${coverageDone}/${coverage.length}｜${coverageRate}%`;document.getElementById('coverageFill').style.width=`${coverageRate}%`;document.getElementById('titleValue').textContent=t.level>=10?'傳說飼主':t.level>=7?'默契搭檔':t.level>=4?'寵物訓練師':'新手飼主';document.getElementById('bossTitle').textContent=`${boss.subject}｜${boss.date.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}`;document.getElementById('bossScope').textContent=boss.scope;document.getElementById('bossCountdown').textContent=examResults[boss.key]?'已通關':remain===0?'今天開戰':remain>0?`D-${remain}`:'等待補登';document.getElementById('questMatrix').innerHTML=quadrants.map(([key,title,tip])=>{const list=qs.filter(q=>q.quadrant===key);return`<section class="quadrant" data-quadrant="${key}"><div class="quadrant-head"><div><div class="quadrant-title">${title}</div><div class="small">${tip}</div></div><span class="quadrant-count">${list.length} 關</span></div><div class="quadrant-list">${list.length?list.map(taskCard).join(''):'<div class="quadrant-empty">拖到這裡建立新分類 ✦</div>'}</div></section>`}).join('');wireTaskCards();renderStats();renderSchedule();renderWeek();renderPet();renderTimer();renderFocusGoal();renderDistractions();renderReview();renderExam()}
