function clearDragUi(){document.querySelectorAll('.drag-over,.dragging,.drag-source').forEach(el=>el.classList.remove('drag-over','dragging','drag-source'));dragState?.ghost?.remove();dragState=null;document.onpointermove=null;document.onpointerup=null;document.onpointercancel=null}
function markDropTarget(x,y){document.querySelectorAll('.quadrant').forEach(el=>el.classList.remove('drag-over'));const target=document.elementFromPoint(x,y)?.closest('.quadrant[data-quadrant]');target?.classList.add('drag-over');return target}
function startTouchDrag(card,id,event){clearDragUi();const rect=card.getBoundingClientRect(),ghost=card.cloneNode(true);ghost.className='quest drag-ghost';ghost.removeAttribute('draggable');ghost.style.width=`${Math.min(rect.width,420)}px`;document.body.appendChild(ghost);card.classList.add('drag-source');dragState={id,ghost};const move=e=>{ghost.style.left=`${Math.min(e.clientX+12,window.innerWidth-ghost.offsetWidth-8)}px`;ghost.style.top=`${Math.min(e.clientY+12,window.innerHeight-ghost.offsetHeight-8)}px`;markDropTarget(e.clientX,e.clientY)};move(event);document.onpointermove=e=>{e.preventDefault();move(e)};document.onpointerup=e=>{const target=markDropTarget(e.clientX,e.clientY),quadrant=target?.dataset.quadrant,taskId=dragState?.id;clearDragUi();if(taskId&&quadrant)moveTask(taskId,quadrant)};document.onpointercancel=clearDragUi}
function wireTaskCards(){document.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>toggleTask(el.dataset.check,el.checked)));document.querySelectorAll('[data-delete]').forEach(el=>el.addEventListener('click',()=>deleteTask(el.dataset.delete)));document.querySelectorAll('[data-edit]').forEach(el=>el.addEventListener('click',()=>openTaskEditor(el.dataset.edit)));document.querySelectorAll('[data-review]').forEach(el=>el.addEventListener('click',()=>openReflection(el.dataset.review)));document.querySelectorAll('.quest').forEach(card=>{card.addEventListener('dragstart',event=>{if(event.target.closest('button:not(.drag-handle),input')){event.preventDefault();return}dragState={id:card.dataset.task};card.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',card.dataset.task)});card.addEventListener('dragend',clearDragUi);card.querySelector('.drag-handle').addEventListener('pointerdown',event=>{if(event.pointerType!=='mouse'){event.preventDefault();startTouchDrag(card,card.dataset.task,event)}})});document.querySelectorAll('.quadrant[data-quadrant]').forEach(zone=>{zone.addEventListener('dragover',event=>{event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('.quadrant').forEach(el=>el.classList.toggle('drag-over',el===zone))});zone.addEventListener('dragleave',event=>{if(!zone.contains(event.relatedTarget))zone.classList.remove('drag-over')});zone.addEventListener('drop',event=>{event.preventDefault();const id=event.dataTransfer.getData('text/plain')||dragState?.id,quadrant=zone.dataset.quadrant;clearDragUi();if(id&&quadrant)moveTask(id,quadrant)})})}
const wireTaskCardsBase=wireTaskCards;wireTaskCards=function(){wireTaskCardsBase();document.querySelectorAll('[data-revive]').forEach(button=>button.onclick=()=>scheduleRevival(button.dataset.revive))};
function revivalDatesFor(q){const base=new Date(`${q.date||iso(selected)}T00:00:00`),first=add(base,1),second=add(base,3),nextExam=tests.find(test=>test.date>base&&(test.subject.includes(q.subject)||q.subject.includes(test.subject))),examReview=nextExam?add(nextExam.date,-1):null,third=examReview&&examReview>second?examReview:add(base,7);return[first,second,third]}
async function scheduleRevival(id){const q=findTask(id);if(!q||q.revive)return;const existing=reviewRevives.filter(row=>row.source_task_key===q.id);if(existing.length){showToast('這一關已經排入錯題復活');return}const rows=revivalDatesFor(q).map((date,index)=>({user_id:session.user.id,source_task_key:q.id,source_title:q.name.slice(0,160),subject:q.subject.slice(0,40),review_date:iso(date),stage:index+1,completed:false}));setSyncing(true);const {data,error}=await db.from('review_revives').insert(rows).select();setSyncing(false);if(error){console.error(error);showToast('錯題復活安排失敗，請再試一次',true);return}reviewRevives.push(...(data||[]));render();showToast('已安排隔天、3 天後與考前復活 ✦')}
async function moveTask(id,quadrant){if(!quadrants.some(x=>x[0]===quadrant))return;const q=findTask(id);if(!q||q.quadrant===quadrant)return;const previous=q.quadrant;q.quadrant=quadrant;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),quadrant};render();setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').update({quadrant,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id))}else{({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{quadrant})))}setSyncing(false);if(error){q.quadrant=previous;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),quadrant:previous};render();showToast('分類移動失敗，請再試一次',true);return}showToast('任務分類已更新')}
function openTaskCreator(){const form=document.getElementById('customQuestForm');editingTaskId=null;form.reset();form.elements.editId.value='';document.getElementById('questDialogTitle').textContent='建立自訂關卡';document.getElementById('customQuestDate').textContent=`${selected.toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'})}的新任務`;document.getElementById('questSubmitButton').textContent='加入今日任務';document.getElementById('questDialog').showModal()}
function openTaskEditor(id){const q=findTask(id);if(!q)return;const form=document.getElementById('customQuestForm');editingTaskId=id;form.elements.editId.value=id;form.elements.subject.value=q.subject;form.elements.time.value=(q.time||'19:00').split('–')[0];form.elements.name.value=q.name;form.elements.clear.value=q.clear;form.elements.xp.value=String(q.xp);form.elements.quadrant.value=q.quadrant;document.getElementById('questDialogTitle').textContent='編輯任務';document.getElementById('customQuestDate').textContent=`${selected.toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'})}・修改後自動同步`;document.getElementById('questSubmitButton').textContent='儲存修改';document.getElementById('questDialog').showModal()}
async function syncHomeworkFromTask(q,value){if(q.source_type!=='homework'||!q.source_key)return;homeworkProgress[q.source_key]=value;saveHomeworkProgress();const row={user_id:session.user.id,source_key:q.source_key,source_date:q.source_date||q.date,category:q.source_category||'todayHW',subject:q.subject,title:q.name,completed:value,updated_at:new Date().toISOString()};const {error}=await db.from('homework_progress').upsert(row,{onConflict:'user_id,source_key'});if(error){console.error(error);showToast('任務已完成，但功課同步稍後再試',true)}renderHomework()}
async function toggleTask(id,value){const q=findTask(id);if(!q)return;const oldLevel=totals().level,previous=q.completed;q.completed=value;if(!q.custom&&!q.revive)overrides[q.id]={...(overrides[q.id]||{}),completed:value};render();setSyncing(true);let error;if(q.revive){({error}=await db.from('review_revives').update({completed:value,updated_at:new Date().toISOString()}).eq('id',q.revive_id).eq('user_id',session.user.id));if(!error){const row=reviewRevives.find(item=>item.id===q.revive_id);if(row)row.completed=value}}else if(q.custom){({error}=await db.from('custom_tasks').update({completed:value,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id))}else{({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{completed:value})))}setSyncing(false);if(error){q.completed=previous;if(!q.custom&&!q.revive)overrides[q.id]={...(overrides[q.id]||{}),completed:previous};showToast('同步失敗，請再試一次',true);render();return}await syncHomeworkFromTask(q,value);const newLevel=totals().level;if(value){burst();petTalk(newLevel>oldLevel?'升級了！來餵我吃飯吧！':'好厲害！又完成一關。');showToast(q.revive?'錯題復活通關，記憶更穩了！':newLevel>oldLevel?`升級！Level ${newLevel}・獲得一次餵食機會`:'任務完成，XP 已存檔')}}
async function deleteTask(id){const q=findTask(id);if(!q)return;setSyncing(true);let error;if(q.revive){({error}=await db.from('review_revives').delete().eq('id',q.revive_id).eq('user_id',session.user.id));if(!error)reviewRevives=reviewRevives.filter(row=>row.id!==q.revive_id)}else if(q.custom){({error}=await db.from('custom_tasks').delete().eq('id',q.id).eq('user_id',session.user.id));if(!error)customQuests=customQuests.filter(x=>x.id!==q.id)}else{const current=overrides[q.id]||{};({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{deleted:true})));if(!error)overrides[q.id]={...current,deleted:true,quadrant:current.quadrant||q.quadrant}}setSyncing(false);if(error){showToast('刪除失敗，請再試一次',true);return}render();showToast('關卡已刪除')}
function taskMinutes(time){const parts=String(time).split('–');if(parts.length!==2)return 0;const toMinutes=value=>{const [hour,minute]=value.split(':').map(Number);return Number.isFinite(hour)&&Number.isFinite(minute)?hour*60+minute:0};return Math.max(0,toMinutes(parts[1])-toMinutes(parts[0]))}
function studyTimeLabel(minutes){const hours=Math.floor(minutes/60),rest=minutes%60;return hours?`${hours} 小時${rest?` ${rest} 分`:''}`:`${rest} 分`}
function renderExamPlanTable(){const body=document.getElementById('examPlanTableBody');if(!body)return;const dates=Object.keys(examSprintPlan).sort(),rows=dates.map(date=>{const d=new Date(date+'T00:00:00'),quests=rawMissionsFor(d).filter(q=>!q.custom),required=quests.filter(q=>q.required),bonus=quests.filter(q=>!q.required&&q.type!=='停機'),done=required.filter(q=>q.completed).length,minutes=required.reduce((sum,q)=>sum+taskMinutes(q.time),0);return{date,d,required,bonus,done,minutes}}),totalRequired=rows.reduce((sum,row)=>sum+row.required.length,0),totalMinutes=rows.reduce((sum,row)=>sum+row.minutes,0);document.getElementById('examPlanSummary').textContent=`${totalRequired} 個必讀關卡・約 ${studyTimeLabel(totalMinutes)}`;body.innerHTML=rows.map(row=>`<tr class="${row.date===iso(selected)?'current':''}"><td><button type="button" class="plan-date-button" data-plan-date="${row.date}">${row.d.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'})}</button></td><td><div class="plan-task-list">${row.required.map(q=>`<div class="plan-task ${q.completed?'done':''}"><span>${esc(q.time)}</span><b>${esc(q.subject)}</b>・${esc(q.name)}</div>`).join('')||'—'}</div></td><td><b class="plan-duration">${studyTimeLabel(row.minutes)}</b></td><td><div class="plan-bonus-list">${row.bonus.map(q=>`<div>${esc(q.subject)}・${esc(q.name)}</div>`).join('')||'—'}</div></td><td><span class="plan-progress ${row.done===row.required.length?'complete':''}">${row.done}/${row.required.length}</span></td></tr>`).join('');body.querySelectorAll('[data-plan-date]').forEach(button=>button.onclick=()=>{selected=new Date(button.dataset.planDate+'T00:00:00');render();document.querySelector('[data-panel="todayPanel"]').click();window.scrollTo({top:0,behavior:'smooth'})})}
function startOfWeek(date){const d=new Date(date);d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d}
function renderWeek(){const calendar=document.getElementById('weekCalendar');if(!calendar)return;if(!weekCursor)weekCursor=startOfWeek(selected);const days=Array.from({length:7},(_,i)=>add(weekCursor,i)),today=new Date();today.setHours(0,0,0,0);const weekly=days.flatMap(d=>missionsFor(d)),done=weekly.filter(q=>q.completed).length,required=weekly.filter(q=>q.required),requiredDone=required.filter(q=>q.completed).length;document.getElementById('weekRange').textContent=`${days[0].toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}－${days[6].toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}`;document.getElementById('weekSummary').innerHTML=`<span>本週 ${weekly.length} 關</span><span>已完成 ${done} 關</span><span>${required.length?`必讀 ${requiredDone}/${required.length}`:'自由安排週'}</span>`;calendar.innerHTML=days.map(d=>{const qs=missionsFor(d),dn=qs.filter(q=>q.completed).length,rate=qs.length?Math.round(dn/qs.length*100):0,visible=qs.slice(0,5);return`<article class="week-day ${iso(d)===iso(selected)?'is-selected':''} ${iso(d)===iso(today)?'is-today':''}"><button class="week-day-head" type="button" data-week-open="${iso(d)}"><small>${d.toLocaleDateString('zh-TW',{weekday:'short'})}</small><b>${d.getMonth()+1}/${d.getDate()}</b><span> ${dn}/${qs.length} 完成</span></button><div class="week-day-progress"><i style="width:${rate}%"></i></div><div class="week-day-tasks">${visible.length?visible.map(q=>`<button class="week-task ${q.completed?'done':''}" type="button" data-week-task="${esc(q.id)}" data-week-date="${iso(d)}"><time>${esc(q.time)}</time><b>${esc(q.subject)}・${esc(q.name)}</b></button>`).join(''):'<div class="week-empty">今天還沒有關卡</div>'}${qs.length>visible.length?`<div class="week-more">還有 ${qs.length-visible.length} 關</div>`:''}</div><button class="week-add" type="button" data-week-add="${iso(d)}">＋ 加入這天</button></article>`}).join('');calendar.querySelectorAll('[data-week-open]').forEach(button=>button.onclick=()=>{selected=new Date(button.dataset.weekOpen+'T00:00:00');render();document.querySelector('[data-panel="todayPanel"]').click()});calendar.querySelectorAll('[data-week-add]').forEach(button=>button.onclick=()=>{selected=new Date(button.dataset.weekAdd+'T00:00:00');render();openTaskCreator()});calendar.querySelectorAll('[data-week-task]').forEach(button=>button.onclick=()=>{selected=new Date(button.dataset.weekDate+'T00:00:00');render();openTaskEditor(button.dataset.weekTask)})}
function petStage(){return petState.fed_count>=5?3:petState.fed_count>=2?2:1}
function petStorageKey(){return session?`study-quest-pet-${session.user.id}`:'study-quest-pet-guest'}
function petPayload(){return{user_id:session.user.id,pet_type:petState.pet_type,pet_name:petState.pet_name,fed_count:petState.fed_count,last_fed_level:petState.last_fed_level,spent_xp:petState.spent_xp,inventory:petState.inventory,updated_at:new Date().toISOString()}}
