function petTalk(message){const companion=document.getElementById('petCompanion');document.getElementById('companionBubble').textContent=message;companion.classList.add('talking');clearTimeout(petBubbleTimer);petBubbleTimer=setTimeout(()=>companion.classList.remove('talking'),3500)}
function playPetMotion(kind){if(petMotionBusy||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const actions={walk:{duration:3200,message:'我走一圈再陪你讀！'},roll:{duration:1550,message:'看我的打滾絕技！'},hop:{duration:1250,message:'跳一下，精神回來了！'},wiggle:{duration:1350,message:'動一動，繼續加油！'}},keys=Object.keys(actions),name=kind&&actions[kind]?kind:keys[Math.floor(Math.random()*keys.length)],action=actions[name],className=`pet-action-${name}`,companion=document.getElementById('petCompanion'),roomImage=document.getElementById('petRoomImage');petMotionBusy=true;petTalk(action.message);companion.classList.add(className);roomImage.classList.add(className);setTimeout(()=>{companion.classList.remove(className);roomImage.classList.remove(className);petMotionBusy=false},action.duration+80)}
function schedulePetMotion(){clearTimeout(petMotionTimer);petMotionTimer=setTimeout(()=>{if(!document.hidden&&session)playPetMotion();schedulePetMotion()},11000+Math.floor(Math.random()*8000))}
function forestTreeFor(subject=''){if(subject.includes('數學'))return{type:'math',icon:'🍁'};if(subject.includes('物理'))return{type:'physics',icon:'🌲'};if(subject.includes('化學'))return{type:'chemistry',icon:'🌳'};if(subject.includes('生物'))return{type:'biology',icon:'🌿'};return{type:'other',icon:'🌸'}}
function forestWeekBounds(date=new Date()){const start=startOfWeek(date),end=add(start,6),next=add(start,7);return{start,end,next,startIso:iso(start),endIso:iso(end)}}
function forestWeekStart(){return forestWeekBounds().startIso}
function forestVisiblePlants(){const{startIso,endIso}=forestWeekBounds();return forestPlants.filter(plant=>forestFilter==='all'||(plant.plant_date>=startIso&&plant.plant_date<=endIso))}
function renderForest(){const scene=document.getElementById('forestPlants');if(!scene)return;const bounds=forestWeekBounds(),visible=forestVisiblePlants(),shown=visible.slice(0,84),week=forestPlants.filter(plant=>plant.plant_date>=bounds.startIso&&plant.plant_date<=bounds.endIso),minutes=forestPlants.reduce((sum,plant)=>sum+(Number(plant.focus_minutes)||45),0),range=`${bounds.start.getMonth()+1}/${bounds.start.getDate()}－${bounds.end.getMonth()+1}/${bounds.end.getDate()}`;document.getElementById('forestRangeTitle').textContent=forestFilter==='all'?'全部森林紀錄':`本週森林｜${range}`;document.getElementById('forestTreeCount').textContent=`${visible.length} 棵樹`;document.getElementById('forestTotalTrees').textContent=forestPlants.length;document.getElementById('forestTotalMinutes').textContent=minutes;document.getElementById('forestWeekTrees').textContent=week.length;document.getElementById('forestRefreshNote').textContent=`每週一 00:00 刷新｜本週已長出 ${week.length} 棵，下次 ${bounds.next.getMonth()+1}/${bounds.next.getDate()} 換新森林`;document.getElementById('forestEmpty').classList.toggle('hidden',visible.length>0);document.getElementById('forestScene').dataset.density=shown.length>=24?'lush':shown.length>=10?'dense':'growing';scene.innerHTML=shown.map((plant,index)=>{const tree=forestTreeFor(plant.subject),focus=Number(plant.focus_minutes)||45,size=focus<=15?'sprout':focus<=25?'sapling':'grown';return`<div class="focus-tree ${tree.type} ${size}" style="animation-delay:${Math.min(index*.025,.45)}s" title="${esc(plant.subject)}・${esc(plant.task_title||'專注任務')}・${focus} 分鐘"><span class="tree-crown">${tree.icon}</span><span class="tree-label">${esc(plant.subject)} ${focus}m</span></div>`}).join('');document.getElementById('forestLog').innerHTML=forestPlants.slice(0,8).map(plant=>{const tree=forestTreeFor(plant.subject),date=new Date(`${plant.plant_date}T00:00:00`).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'});return`<article class="forest-log-item"><span class="log-tree">${tree.icon}</span><div><b>${esc(plant.subject)}・${esc(plant.task_title||'專注任務')}</b><small>${date}・${Number(plant.focus_minutes)||45} 分鐘</small></div></article>`}).join('')||'<div class="forest-log-empty">完成第一輪專注後，成長紀錄會出現在這裡。</div>';const level=totals().level;document.getElementById('titleValue').textContent=level>=10?'傳說森林守護者':level>=7?'茂盛造林師':level>=4?'森林培育員':'新芽守護者'}
function forestSeasonFor(date=new Date()){const month=date.getMonth()+1;if(month===12)return{key:'christmas',label:'🎄 聖誕雪夜',particle:'❄'};if(month<=2)return{key:'winter',label:'❄️ 冬日森林',particle:'❄'};if(month<=5)return{key:'spring',label:'🌸 春日花林',particle:'🌸'};if(month<=8)return{key:'summer',label:'☀️ 夏日森林',particle:'✦'};return{key:'autumn',label:'🍁 秋日森林',particle:'🍂'}}
function renderSeason(){const scene=document.getElementById('forestScene'),badge=document.getElementById('forestSeasonBadge'),particles=document.getElementById('seasonParticles');if(!scene||!badge||!particles)return;const season=forestSeasonFor();scene.dataset.season=season.key;badge.textContent=season.label;particles.innerHTML=Array.from({length:14},(_,index)=>`<span class="season-particle" style="--x:${(index*37)%96}%;--y:${10+(index*23)%75}%;--size:${.65+(index%4)*.18}rem;--speed:${7+(index%5)*1.6}s;--delay:-${(index*1.3).toFixed(1)}s;--drift:${index%2?38:-42}px">${season.particle}</span>`).join('')}
const renderForestBase=renderForest;renderForest=function(){renderSeason();return renderForestBase()};
async function loadForest(){const {data,error}=await db.from('focus_forest').select('*').eq('user_id',session.user.id).order('planted_at',{ascending:false}).limit(500);if(error){console.error(error);forestPlants=[];return}forestPlants=data||[]}
async function plantFocusTree(){if(!session)return;const task=focusTimer.goal_task_key?allMissions().find(q=>q.id===focusTimer.goal_task_key):null,subject=task?.subject||'自由專注',tree=forestTreeFor(subject),row={user_id:session.user.id,plant_date:iso(new Date()),task_key:task?.id||null,task_title:task?.name||'自由專注',subject,tree_type:tree.type,focus_minutes:workMinutes};const {data,error}=await db.from('focus_forest').insert(row).select().single();if(error){console.error(error);showToast('專注完成，但樹苗同步失敗，請稍後再試',true);return}forestPlants.unshift(data);renderForest();showToast(`${subject}完成 ${workMinutes} 分鐘，森林長出${workMinutes===15?'一株幼苗':workMinutes===25?'一棵小樹':'一棵大樹'}！`)}
