async function handleSession(next){if(loadingUser===next?.user?.id)return;session=next||null;if(!session){loadingUser=null;clearInterval(timerInterval);timerInterval=null;stopFocusSound();document.getElementById('authScreen').classList.remove('hidden');document.getElementById('loadingMask').classList.add('hidden');return}loadingUser=session.user.id;document.getElementById('authScreen').classList.add('hidden');document.getElementById('loadingMask').classList.remove('hidden');try{loadFocusSound();loadFocusRescueState();await loadUserData();updateAccountUi();render();startTimerLoop();syncFocusSound();if(focusTimer.running&&timerRemaining()<=0)await advanceTimer();document.getElementById('loadingMask').classList.add('hidden')}catch(error){console.error(error);document.getElementById('loadingMask').classList.add('hidden');showToast('資料載入失敗，請重新整理',true)}finally{loadingUser=null}}
async function signIn(){document.getElementById('authError').textContent='';const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:SITE_URL,queryParams:{prompt:'select_account'}}});if(error)document.getElementById('authError').textContent='登入沒有成功，請再試一次'}
async function signOut(){await db.auth.signOut();clearInterval(timerInterval);timerInterval=null;stopFocusSound();setTimerFocus(false);clearPhotoPreview();profile={headline:'with great power comes great responsibility',theme:'pink',display_name:''};customQuests=[];overrides={};reflections={};distractions=[];distractionLog=[];rescueStep='';workMinutes=45;examResults={};petState=defaultPetState();petCloudReady=false;weekCursor=null;selectedReflectionTaskId=null;focusTimer=defaultTimer();session=null;document.getElementById('settingsDialog').close();document.getElementById('authScreen').classList.remove('hidden')}
async function switchAccount(){await db.auth.signOut();await signIn()}
function wireUi(){document.getElementById('googleSignIn').onclick=signIn;document.getElementById('accountButton').onclick=()=>{document.getElementById('headlineInput').value=profile.headline;document.querySelector(`input[name="theme"][value="${profile.theme}"]`).checked=true;document.getElementById('settingsDialog').showModal()};document.getElementById('closeSettings').onclick=()=>document.getElementById('settingsDialog').close();document.getElementById('signOutButton').onclick=signOut;document.getElementById('switchAccountButton').onclick=switchAccount;document.getElementById('timerStartPause').onclick=toggleTimer;document.getElementById('timerReset').onclick=resetTimer;document.getElementById('timerFullscreen').onclick=toggleTimerFocus;document.getElementById('timerRescue').onclick=openRescueDialog;document.querySelectorAll('[data-timer-minutes]').forEach(button=>button.onclick=()=>setWorkMinutes(button.dataset.timerMinutes));document.querySelectorAll('[data-rescue]').forEach(button=>button.onclick=handleRescue);document.getElementById('closeRescueDialog').onclick=()=>document.getElementById('rescueDialog').close();document.getElementById('rescueStepForm').addEventListener('submit',saveRescueStep);document.querySelectorAll('[data-focus-sound]').forEach(button=>button.onclick=chooseFocusSound);document.getElementById('focusSoundVolume').oninput=changeFocusSoundVolume;document.getElementById('focusGoalSelect').onchange=changeFocusGoal;document.getElementById('distractionForm').addEventListener('submit',addDistraction);document.getElementById('focusQuickPark').addEventListener('submit',addQuickDistraction);document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)setTimerFocus(false)});document.getElementById('reflectionTask').onchange=selectReflectionTask;document.getElementById('notePhotoInput').onchange=selectNotePhoto;document.getElementById('reflectionForm').addEventListener('submit',saveReflection);document.getElementById('learnedText').addEventListener('input',()=>{reviewDirty=true});document.getElementById('reflectionText').addEventListener('input',()=>{reviewDirty=true});document.getElementById('scoreSubject').onchange=event=>{scoreSubject=event.target.value;renderScoreChart()};document.getElementById('scoreForm').addEventListener('submit',saveExamResult);document.getElementById('cancelScoreDialog').onclick=()=>document.getElementById('scoreDialog').close();document.getElementById('prevDay').onclick=()=>{if(selected>start){selected=add(selected,-1);weekCursor=startOfWeek(selected);render()}};document.getElementById('nextDay').onclick=()=>{if(selected<end){selected=add(selected,1);weekCursor=startOfWeek(selected);render()}};document.getElementById('prevWeek').onclick=()=>{weekCursor=add(weekCursor||startOfWeek(selected),-7);renderWeek()};document.getElementById('nextWeek').onclick=()=>{weekCursor=add(weekCursor||startOfWeek(selected),7);renderWeek()};document.getElementById('thisWeek').onclick=()=>{const today=new Date();today.setHours(0,0,0,0);weekCursor=startOfWeek(today);renderWeek()};document.getElementById('feedPet').onclick=feedPet;document.getElementById('savePetName').onclick=savePetName;document.querySelectorAll('[data-pet]').forEach(button=>button.onclick=()=>switchPet(button.dataset.pet));document.getElementById('petCompanion').onclick=()=>document.querySelector('[data-panel="statsPanel"]').click();document.querySelectorAll('.nav-btn').forEach(btn=>btn.onclick=()=>{renderStats();renderSchedule();renderWeek();renderPet();renderExam();document.querySelectorAll('.nav-btn,.panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById(btn.dataset.panel).classList.add('active')});const questDialog=document.getElementById('questDialog'),questForm=document.getElementById('customQuestForm');document.getElementById('openQuestDialog').onclick=openTaskCreator;document.getElementById('cancelQuestDialog').onclick=()=>questDialog.close();questDialog.addEventListener('close',()=>{editingTaskId=null});questForm.addEventListener('submit',saveQuest);document.getElementById('settingsForm').addEventListener('submit',saveSettings)}
async function saveQuest(event){event.preventDefault();const data=new FormData(event.currentTarget),xpRaw=Number(data.get('xp')),values={subject:String(data.get('subject')).trim().slice(0,20),name:String(data.get('name')).trim().slice(0,50),time:String(data.get('time')),clear:String(data.get('clear')).trim().slice(0,80),xp:Number.isFinite(xpRaw)?Math.min(200,Math.max(0,Math.round(xpRaw/5)*5)):30,quadrant:String(data.get('quadrant'))};if(!values.subject||!values.name||!values.clear||!quadrants.some(x=>x[0]===values.quadrant))return;setSyncing(true);if(editingTaskId){const q=findTask(editingTaskId);let error;if(!q){setSyncing(false);showToast('找不到這個任務',true);return}if(q.custom){({error}=await db.from('custom_tasks').update({subject:values.subject,title:values.name,start_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id));if(!error)Object.assign(q,values)}else{const patch={subject:values.subject,task_name:values.name,task_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant};({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,patch)));if(!error)overrides[q.id]={...(overrides[q.id]||{}),...patch}}setSyncing(false);if(error){showToast('修改失敗，請再試一次',true);return}document.getElementById('questDialog').close();render();showToast('任務修改已同步');return}const row={user_id:session.user.id,task_date:iso(selected),subject:values.subject,title:values.name,start_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant,completed:false};const {data:created,error}=await db.from('custom_tasks').insert(row).select().single();setSyncing(false);if(error){showToast('新增失敗，請再試一次',true);return}customQuests.push(normalizeCustom(created));document.getElementById('questDialog').close();render();showToast('新關卡已加入！')}
async function saveSettings(event){event.preventDefault();const data=new FormData(event.currentTarget),next={headline:String(data.get('headline')).trim().slice(0,80)||'with great power comes great responsibility',theme:String(data.get('theme'))};setSyncing(true);const {error}=await db.from('profiles').update({...next,updated_at:new Date().toISOString()}).eq('user_id',session.user.id);setSyncing(false);if(error){showToast('設定儲存失敗',true);return}profile={...profile,...next};document.getElementById('settingsDialog').close();render();showToast('個人風格已儲存')}
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;c.registerTool({name:'get_today_study_missions',title:'讀取今日任務',description:'取得目前選取日期的讀書任務與完成狀態。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({date:iso(selected),missions:missionsFor(selected).map(q=>({id:q.id,subject:q.subject,title:q.name,status:q.completed?'completed':'pending',quadrant:q.quadrant,xp:q.xp}))})})}
function wirePetMotion(){document.getElementById('petPlayAction').onclick=()=>playPetMotion();document.getElementById('petCompanion').addEventListener('click',()=>playPetMotion());document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedulePetMotion()});schedulePetMotion()}
async function bootstrap(){wireUi();wireForest();wireHomework();registerWebMCP();const {data:{session:initial}}=await db.auth.getSession();await handleSession(initial);db.auth.onAuthStateChange((_event,next)=>setTimeout(()=>handleSession(next),0))}
bootstrap();

